#' nitrogen levels in sub-plots, in three replications.
#'
#' @format A data frame with 36 rows and 7 variables:
#' \describe{
#'   \item{rep}{Factor, replication (R1-R3).}
#'   \item{irrigation}{Factor, main-plot irrigation level.}
#'   \item{nitrogen}{Factor, sub-plot nitrogen level (kg N/ha; foliar =
#'     additional 2\% urea spray).}
#'   \item{seed_yield}{Seed yield (kg/ha).}
#'   \item{water_use}{Seasonal water use (mm).}
#'   \item{wue}{Water use efficiency (kg/ha per mm).}
#'   \item{stover_yield}{Stover yield (kg/ha).}
#' }
#' @source Simulated with \code{data-raw/make_datasets.R} (seed 2026).
#'   Not real experimental data.
#' @examples
#' data(clusterbean_spd)
#' anova_spd(clusterbean_spd, "seed_yield", "irrigation", "nitrogen", "rep")
"clusterbean_spd"

#' Pearl Millet Multi-Environment Trial (Simulated)
